"""Dependency graph with topological ordering."""


class PluginCycleError(Exception):
    """Raised when the plugin dependency graph contains a cycle."""


class PluginGraph:
    def __init__(self):
        self._deps = {}  # node -> set of nodes it depends on

    def add_node(self, name):
        self._deps.setdefault(name, set())

    def add_edge(self, dependent, dependency):
        self.add_node(dependent)
        self.add_node(dependency)
        self._deps[dependent].add(dependency)

    def nodes(self):
        return sorted(self._deps)

    def dependencies_of(self, name):
        return sorted(self._deps.get(name, set()))

    def topo_sort(self):
        """Return node names ordered so every dependency precedes dependents."""
        indegree = {name: 0 for name in self._deps}
        dependents = {name: [] for name in self._deps}
        for node, deps in self._deps.items():
            for dep in deps:
                dependents[dep].append(node)
                indegree[node] += 1
        ready = sorted(n for n, d in indegree.items() if d == 0)
        order = []
        while ready:
            node = ready.pop(0)
            order.append(node)
            for parent in dependents[node]:
                indegree[parent] -= 1
                if indegree[parent] == 0:
                    ready.append(parent)
            ready.sort()
        # Kahn's algorithm cannot remove nodes that are part of a cycle (or
        # depend on one). Returning the prefix would omit declared plugins,
        # so reject the graph instead.
        if len(order) != len(self._deps):
            cyclic_nodes = sorted(set(self._deps) - set(order))
            raise PluginCycleError(
                "plugin dependency cycle detected: " + ", ".join(cyclic_nodes)
            )
        return order

